import firebase_admin
from firebase_admin import auth

def email_password_login(email, password, config=None):
    config = config or {}
    if not firebase_admin._apps:
        firebase_admin.initialize_app()
    user = auth.get_user_by_email(email)
    token = auth.create_custom_token(user.uid)
    return {'id_token': token.decode('utf-8')}

import requests

def refresh_session(refresh_token, config=None):
    config = config or {}
    response = requests.post(
        'https://YOUR_AUTH0_DOMAIN/oauth/token',
        json={
            'grant_type': 'refresh_token',
            'client_id': config['client_id'],
            'client_secret': config['client_secret'],
            'refresh_token': refresh_token
        }
    )
    response.raise_for_status()
    return response.json()

import msal

def password_reset(email, config=None):
    config = config or {}
    app = msal.ConfidentialClientApplication(
        config['client_id'],
        authority=config['authority'],
        client_credential=config['client_secret']
    )
    result = app.acquire_token_for_client(scopes=[config['scope']],
                                          password_reset_email=email)
    if 'error' in result:
        raise Exception(result['error_description'])
    return result

import os

def get_config():
    return {
        'firebase': {
            'api_key': os.getenv('FIREBASE_API_KEY'),
            'auth_domain': os.getenv('FIREBASE_AUTH_DOMAIN')
        },
        'auth0': {
            'client_id': os.getenv('AUTH0_CLIENT_ID'),
            'client_secret': os.getenv('AUTH0_CLIENT_SECRET'),
            'domain': os.getenv('AUTH0_DOMAIN')
        },
        'azure': {
            'client_id': os.getenv('AZURE_CLIENT_ID'),
            'client_secret': os.getenv('AZURE_CLIENT_SECRET'),
            'authority': os.getenv('AZURE_AUTHORITY'),
            'scope': os.getenv('AZURE_SCOPE')
        }
    }

class UserRequest:
    def __init__(self, email, password):
        self.email = email
        self.password = password

class UserResponse:
    def __init__(self, user_id):
        self.user_id = user_id

class TokenRequest:
    def __init__(self, refresh_token):
        self.refresh_token = refresh_token

class TokenResponse:
    def __init__(self, access_token, refresh_token):
        self.access_token = access_token
        self.refresh_token = refresh_token
